import * as React from "react";

export type PhotoStripIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function PhotoStripIcon({ size = 20, ...props }: PhotoStripIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="6" y="3.5" width="12" height="17" rx="1" /><circle cx="10" cy="8" r="1.5" /><circle cx="14" cy="13" r="1.5" />
    </svg>
  );
}
